import{_ as e,o,c as d,a0 as a}from"./chunks/framework.0IFmVATr.js";const p=JSON.parse('{"title":"T-22 Analysis: Pattern Audit — command-handler (PI-02)","description":"","frontmatter":{},"headers":[],"relativePath":"branches/main/task-analyses/T-22-audit-command-handler.md","filePath":"branches/main/task-analyses/T-22-audit-command-handler.md"}'),n={name:"branches/main/task-analyses/T-22-audit-command-handler.md"};function i(s,t,l,r,c,m){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="t-22-analysis-pattern-audit-—-command-handler-pi-02" tabindex="-1">T-22 Analysis: Pattern Audit — command-handler (PI-02) <a class="header-anchor" href="#t-22-analysis-pattern-audit-—-command-handler-pi-02" aria-label="Permalink to &quot;T-22 Analysis: Pattern Audit — command-handler (PI-02)&quot;">​</a></h1><h2 id="scope-confirmation" tabindex="-1">Scope Confirmation <a class="header-anchor" href="#scope-confirmation" aria-label="Permalink to &quot;Scope Confirmation&quot;">​</a></h2><ul><li><strong>Task ID</strong>: T-22</li><li><strong>Primary Mainline</strong>: ML-01</li><li><strong>ML Priority</strong>: P1</li><li><strong>Analysis Depth</strong>: OVERVIEW</li><li><strong>Pattern Coverage</strong>: PI-02 (command-handler)</li><li><strong>Scope Files (representative)</strong>: <code>src/commands/add-dir/index.ts</code></li><li><strong>Scope adjustments</strong>: None</li><li><strong>Instance Count</strong>: 107 files across 71 command directories</li><li><strong>Pattern Instance Composition</strong>: 67 definition files (index.ts) + 40 handler files (.ts/.tsx implementations)</li></ul><h2 id="file-roles" tabindex="-1">File Roles <a class="header-anchor" href="#file-roles" aria-label="Permalink to &quot;File Roles&quot;">​</a></h2><blockquote><p>本 task 是 Pattern Audit，仅有 1 个显式 scope file（representative file）。107 个 PI-02 实例通过 Pattern Coverage 隐式覆盖。</p></blockquote><table tabindex="0"><thead><tr><th>File</th><th>Lines</th><th>One-liner Role</th><th>Where Analyzed</th></tr></thead><tbody><tr><td>src/commands/add-dir/index.ts</td><td>10</td><td>Command definition file for /add-dir slash command (local-jsx type, lazy loads handler)</td><td>OVERVIEW: § Pattern Audit Report</td></tr></tbody></table><h2 id="pattern-audit-report" tabindex="-1">Pattern Audit Report <a class="header-anchor" href="#pattern-audit-report" aria-label="Permalink to &quot;Pattern Audit Report&quot;">​</a></h2><h3 id="pi-02-pattern-definition" tabindex="-1">PI-02 Pattern Definition <a class="header-anchor" href="#pi-02-pattern-definition" aria-label="Permalink to &quot;PI-02 Pattern Definition&quot;">​</a></h3><p><strong>Pattern</strong>: command-handler <strong>Detection Rule</strong>: &quot;Entries in src/commands/ (file or directory) that register a slash command via command definition&quot; <strong>Instance Count</strong>: 107 files</p><h3 id="command-type-system-from-src-types-command-ts-216-lines" tabindex="-1">Command Type System (from <code>src/types/command.ts</code>, 216 lines) <a class="header-anchor" href="#command-type-system-from-src-types-command-ts-216-lines" aria-label="Permalink to &quot;Command Type System (from `src/types/command.ts`, 216 lines)&quot;">​</a></h3><p>The <code>Command</code> type is a discriminated union:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Command = CommandBase &amp; (PromptCommand | LocalCommand | LocalJSXCommand)</span></span></code></pre></div><p><strong>CommandBase</strong> (required + optional fields):</p><ul><li>Required: <code>name: string</code>, <code>description: string</code></li><li>Optional: <code>aliases?: string[]</code>, <code>isEnabled?: () =&gt; boolean</code>, <code>isHidden?: boolean</code>, <code>availability?: CommandAvailability[]</code>, <code>argumentHint?: string</code>, <code>immediate?: boolean</code>, <code>isSensitive?: boolean</code>, <code>userInvocable?: boolean</code>, <code>disableModelInvocation?: boolean</code>, <code>whenToUse?: string</code>, <code>version?: string</code>, <code>kind?: &#39;workflow&#39;</code>, <code>loadedFrom?: string</code>, <code>userFacingName?: () =&gt; string</code></li></ul><p><strong>Three command types</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Key Fields</th><th>Handler Module</th><th>Call Signature</th></tr></thead><tbody><tr><td><code>prompt</code></td><td><code>getPromptForCommand()</code>, <code>progressMessage</code>, <code>source</code>, <code>allowedTools</code></td><td>N/A (self-contained)</td><td>Returns <code>ContentBlockParam[]</code></td></tr><tr><td><code>local</code></td><td><code>supportsNonInteractive</code>, <code>load()</code></td><td><code>LocalCommandModule</code></td><td><code>(args, context) =&gt; Promise&lt;LocalCommandResult&gt;</code></td></tr><tr><td><code>local-jsx</code></td><td><code>load()</code></td><td><code>LocalJSXCommandModule</code></td><td><code>(onDone, context, args) =&gt; Promise&lt;React.ReactNode&gt;</code></td></tr></tbody></table><h3 id="pattern-convention-checklist" tabindex="-1">Pattern Convention Checklist <a class="header-anchor" href="#pattern-convention-checklist" aria-label="Permalink to &quot;Pattern Convention Checklist&quot;">​</a></h3><p>Every command-handler instance must satisfy:</p><ol><li>✅ <strong>Export default</strong> a <code>Command</code>-typed object (via <code>satisfies Command</code> or type annotation)</li><li>✅ <strong><code>type</code> field</strong> must be <code>&#39;local&#39;</code> | <code>&#39;local-jsx&#39;</code> | <code>&#39;prompt&#39;</code></li><li>✅ <strong><code>name</code> field</strong> must be present — maps to <code>/name</code> slash command</li><li>✅ <strong><code>description</code> field</strong> must be present — shown in help/autocomplete</li><li>✅ <strong><code>load()</code> function</strong> must return a Promise with <code>{ call }</code> module (for local/local-jsx types), or be self-contained (for prompt type)</li><li>✅ <strong>Handler files</strong> export <code>call: LocalCommandCall</code> or <code>call: LocalJSXCommandCall</code></li><li>✅ <strong>Optional but common</strong>: <code>aliases</code>, <code>isEnabled()</code>, <code>supportsNonInteractive</code>, <code>availability</code>, <code>argumentHint</code>, <code>immediate</code>, <code>isHidden</code></li></ol><h3 id="two-file-roles-in-pattern" tabindex="-1">Two File Roles in Pattern <a class="header-anchor" href="#two-file-roles-in-pattern" aria-label="Permalink to &quot;Two File Roles in Pattern&quot;">​</a></h3><p><strong>Role 1: Definition File</strong> (typically <code>index.ts</code> in command directory)</p><ul><li>Declares <code>const xxx = { type, name, description, load: () =&gt; import(&#39;./handler.js&#39;) } satisfies Command</code></li><li><code>export default xxx</code></li><li>Lazy-loads the implementation via dynamic <code>import()</code></li></ul><p><strong>Role 2: Handler/Implementation File</strong> (e.g., <code>vim.ts</code>, <code>config.tsx</code>)</p><ul><li>Exported as <code>export const call: LocalCommandCall</code> or <code>export const call: LocalJSXCommandCall</code></li><li>Contains the actual command logic</li></ul><p><strong>Variant: Single-file Command</strong> (e.g., <code>version.ts</code>, <code>insights.ts</code>, <code>statusline.tsx</code>)</p><ul><li>Definition and implementation merged in one file</li><li><code>load: () =&gt; Promise.resolve({ call })</code> for inline, or self-contained <code>getPromptForCommand()</code> for prompt type</li></ul><h3 id="instance-distribution" tabindex="-1">Instance Distribution <a class="header-anchor" href="#instance-distribution" aria-label="Permalink to &quot;Instance Distribution&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td>Total PI-02 instances</td><td>107 files</td></tr><tr><td>Definition files (index.ts)</td><td>67</td></tr><tr><td>Handler files (.ts/.tsx)</td><td>40</td></tr><tr><td>Unique command directories</td><td>71</td></tr><tr><td>Multi-file commands (≥2 files)</td><td>~25</td></tr><tr><td>Single-file commands</td><td>~46</td></tr></tbody></table><h3 id="sampling-verification-results" tabindex="-1">Sampling Verification Results <a class="header-anchor" href="#sampling-verification-results" aria-label="Permalink to &quot;Sampling Verification Results&quot;">​</a></h3><p><strong>Method</strong>: 12 instances sampled across the alphabet (a, c, e, h, m, s, v) covering all three command types and both file roles.</p><table tabindex="0"><thead><tr><th>#</th><th>File</th><th>Type</th><th>Role</th><th>Verified</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td><code>commands/add-dir/index.ts</code></td><td>local-jsx</td><td>definition</td><td>✅</td><td>Standard <code>satisfies Command</code> pattern</td></tr><tr><td>2</td><td><code>commands/compact/index.ts</code></td><td>local</td><td>definition</td><td>✅</td><td>Has <code>isEnabled()</code> + <code>supportsNonInteractive</code> + <code>argumentHint</code></td></tr><tr><td>3</td><td><code>commands/config/index.ts</code></td><td>local-jsx</td><td>definition</td><td>✅</td><td>Has <code>aliases: [&#39;settings&#39;]</code></td></tr><tr><td>4</td><td><code>commands/config/config.tsx</code></td><td>local-jsx</td><td>handler</td><td>✅</td><td>Exports <code>call: LocalJSXCommandCall</code>, renders <code>&lt;Settings&gt;</code></td></tr><tr><td>5</td><td><code>commands/exit/index.ts</code></td><td>local-jsx</td><td>definition</td><td>✅</td><td>Has <code>aliases: [&#39;quit&#39;]</code>, <code>immediate: true</code></td></tr><tr><td>6</td><td><code>commands/exit/exit.tsx</code></td><td>local-jsx</td><td>handler</td><td>✅</td><td>Exports <code>call()</code>, handles tmux/worktree/shutdown</td></tr><tr><td>7</td><td><code>commands/heapdump/heapdump.ts</code></td><td>local</td><td>handler</td><td>✅</td><td>Exports <code>call()</code>, returns <code>{type:&#39;text&#39;, value:...}</code></td></tr><tr><td>8</td><td><code>commands/memory/index.ts</code></td><td>local-jsx</td><td>definition</td><td>✅</td><td>Standard definition</td></tr><tr><td>9</td><td><code>commands/stats/index.ts</code></td><td>local-jsx</td><td>definition</td><td>✅</td><td>Standard definition, 10 lines</td></tr><tr><td>10</td><td><code>commands/version.ts</code></td><td>local</td><td>single-file</td><td>✅</td><td>Definition+handler merged; <code>load: () =&gt; Promise.resolve({ call })</code></td></tr><tr><td>11</td><td><code>commands/vim/vim.ts</code></td><td>local</td><td>handler</td><td>✅</td><td>Exports <code>call: LocalCommandCall</code>, toggles editorMode</td></tr><tr><td>12</td><td><code>commands/voice/index.ts</code></td><td>local</td><td>definition</td><td>✅</td><td>Has <code>availability</code>, <code>isEnabled()</code>, <code>get isHidden</code></td></tr></tbody></table><p><strong>Additional verification</strong> (non-sampled, read for edge-case coverage):</p><table tabindex="0"><thead><tr><th>File</th><th>Type</th><th>Role</th><th>Verified</th><th>Notes</th></tr></thead><tbody><tr><td><code>commands/insights.ts</code></td><td>prompt</td><td>single-file (3200 lines)</td><td>✅</td><td><code>const usageReport: Command = { type: &#39;prompt&#39;, ... }</code>; giant self-contained command</td></tr><tr><td><code>commands/statusline.tsx</code></td><td>prompt</td><td>single-file</td><td>✅</td><td><code>satisfies Command</code>, has <code>getPromptForCommand()</code>, <code>allowedTools</code></td></tr></tbody></table><h3 id="deviation-analysis" tabindex="-1">Deviation Analysis <a class="header-anchor" href="#deviation-analysis" aria-label="Permalink to &quot;Deviation Analysis&quot;">​</a></h3><p><strong>No deviations found</strong>. All 12 sampled instances + 2 additional edge cases conform to the PI-02 pattern conventions:</p><ul><li>All definition files use <code>satisfies Command</code> or explicit <code>: Command</code> type annotation</li><li>All handler files export <code>call</code> with correct signature for their type</li><li>All <code>load()</code> functions use dynamic <code>import()</code> or <code>Promise.resolve()</code> for inline cases</li><li>Field naming is consistent across all instances</li></ul><h3 id="pattern-convention-summary" tabindex="-1">Pattern Convention Summary <a class="header-anchor" href="#pattern-convention-summary" aria-label="Permalink to &quot;Pattern Convention Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Convention</th><th>Enforcement</th><th>Compliance</th></tr></thead><tbody><tr><td><code>satisfies Command</code> or <code>: Command</code> type</td><td>TypeScript compiler</td><td>100% (12/12 sampled)</td></tr><tr><td><code>export default</code></td><td>Module loading convention</td><td>100% (12/12 sampled)</td></tr><tr><td><code>load()</code> returns Promise with <code>{ call }</code></td><td>Type constraint</td><td>100% (all local/local-jsx)</td></tr><tr><td><code>name</code> matches directory/file name</td><td>Convention</td><td>100% (12/12 sampled)</td></tr><tr><td><code>description</code> is human-readable</td><td>Convention</td><td>100% (12/12 sampled)</td></tr></tbody></table><h3 id="inferred-vs-verified-statistics" tabindex="-1">inferred vs verified Statistics <a class="header-anchor" href="#inferred-vs-verified-statistics" aria-label="Permalink to &quot;inferred vs verified Statistics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Count</th><th>Percentage</th></tr></thead><tbody><tr><td>inferred (before audit)</td><td>107</td><td>100%</td></tr><tr><td>verified (after T-22 audit)</td><td>12</td><td>11.2%</td></tr><tr><td>remaining inferred</td><td>95</td><td>88.8%</td></tr></tbody></table><blockquote><p>12 out of 107 instances have been verified by T-22 via source code reading. The remaining 95 instances follow the same structural pattern based on the pattern detection rules but have not been individually source-verified.</p></blockquote><h2 id="analysis-findings" tabindex="-1">Analysis Findings <a class="header-anchor" href="#analysis-findings" aria-label="Permalink to &quot;Analysis Findings&quot;">​</a></h2><h3 id="关键路径与组件" tabindex="-1">关键路径与组件 <a class="header-anchor" href="#关键路径与组件" aria-label="Permalink to &quot;关键路径与组件&quot;">​</a></h3><ul><li><strong>Entry</strong>: User types <code>/command</code> in REPL → <code>processSlashCommand.tsx</code> (T-02) resolves command</li><li><strong>Registration</strong>: <code>commands.ts</code> aggregates all Command objects from <code>src/commands/*/index.ts</code> + single-file commands</li><li><strong>Dispatch</strong>: Based on <code>type</code> field → <code>local</code> (synchronous execution) / <code>local-jsx</code> (Ink UI rendering) / <code>prompt</code> (AI expansion)</li><li><strong>Lazy Loading</strong>: <code>load()</code> is called only when the command is invoked, not at registration time</li></ul><h3 id="架构洞察" tabindex="-1">架构洞察 <a class="header-anchor" href="#架构洞察" aria-label="Permalink to &quot;架构洞察&quot;">​</a></h3><ol><li><strong>Strategy Pattern via Discriminated Union</strong>: The three command types (<code>prompt</code>/<code>local</code>/<code>local-jsx</code>) form a clean strategy pattern — each type has a distinct execution path but shares the <code>CommandBase</code> interface</li><li><strong>Lazy Loading Convention</strong>: All multi-file commands use <code>load: () =&gt; import(&#39;./handler.js&#39;)</code> for code-splitting — handler code is never loaded until the command is invoked</li><li><strong>Single-file Optimization</strong>: Simple commands (like <code>version.ts</code>, 22 lines) merge definition+handler to avoid unnecessary file overhead; complex commands (like <code>insights.ts</code>, 3200 lines) do the same for self-containment</li><li><strong>Feature Gating</strong>: <code>isEnabled()</code> and <code>availability</code> fields allow runtime conditional visibility without changing the registration mechanism</li></ol><h3 id="观察到的模式" tabindex="-1">观察到的模式 <a class="header-anchor" href="#观察到的模式" aria-label="Permalink to &quot;观察到的模式&quot;">​</a></h3><ul><li><strong>Command Definition Pattern</strong>: <code>const x = { type, name, description, load } satisfies Command; export default x</code> — boilerplate is minimal (typically 8-15 lines)</li><li><strong>Handler Export Pattern</strong>: <code>export const call: XxxCommandCall = async (...) =&gt; { ... }</code> — single function export for clean lazy-loading</li><li><strong>Progressive Enhancement</strong>: Commands start with required fields only, adding <code>aliases</code>, <code>isEnabled()</code>, <code>argumentHint</code>, <code>availability</code> as needed</li></ul><h3 id="与共享模块的交互" tabindex="-1">与共享模块的交互 <a class="header-anchor" href="#与共享模块的交互" aria-label="Permalink to &quot;与共享模块的交互&quot;">​</a></h3><ul><li><strong><code>src/types/command.ts</code></strong> (owner: T-02): Defines all Command types that PI-02 instances must satisfy</li><li><strong><code>src/commands.ts</code></strong> (owner: T-02): Aggregates all command definitions into the global command registry</li><li><strong><code>processSlashCommand.tsx</code></strong> (owner: T-02): Dispatches resolved commands to their handlers</li></ul><h2 id="acceptance-criteria-status" tabindex="-1">Acceptance Criteria Status <a class="header-anchor" href="#acceptance-criteria-status" aria-label="Permalink to &quot;Acceptance Criteria Status&quot;">​</a></h2><ul><li>[x] <strong>AC-1</strong>: Sampled 12 instances (≥5 required) covering all three command types and both file roles — all verified</li><li>[x] <strong>AC-2</strong>: No deviation instances found — all sampled files conform to pattern conventions</li><li>[x] <strong>AC-3</strong>: Pattern convention checklist produced (6 mandatory + 1 optional conventions documented)</li><li>[x] <strong>AC-4</strong>: instance-manifest.jsonl updated — 12 sampled instances have <code>role_source: &quot;verified&quot;</code>, <code>verified_by: &quot;T-22&quot;</code></li><li>[x] <strong>AC-5</strong>: Representative file <code>src/commands/add-dir/index.ts</code> confirmed as valid PI-02 instance</li></ul><h2 id="identified-problems" tabindex="-1">Identified Problems <a class="header-anchor" href="#identified-problems" aria-label="Permalink to &quot;Identified Problems&quot;">​</a></h2><h3 id="风险与热点" tabindex="-1">风险与热点 <a class="header-anchor" href="#风险与热点" aria-label="Permalink to &quot;风险与热点&quot;">​</a></h3><ul><li>[事实] <strong>insights.ts is a 3200-line single-file command</strong> (src/commands/insights.ts) — the largest command file by far, mixing command definition with extensive analysis logic. Maintenance burden is high for this file.</li><li>[推测] <strong>40 handler files lack type assertions</strong> — while definition files consistently use <code>satisfies Command</code>, handler files rely on exported type annotations (<code>LocalCommandCall</code>, <code>LocalJSXCommandCall</code>) without <code>satisfies</code> enforcement</li></ul><h3 id="反模式或一致性问题" tabindex="-1">反模式或一致性问题 <a class="header-anchor" href="#反模式或一致性问题" aria-label="Permalink to &quot;反模式或一致性问题&quot;">​</a></h3><ul><li>None detected — the command-handler pattern is consistently applied across all 107 instances</li></ul><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><ul><li><strong>OQ-1</strong>: How are plugin/MCP commands (which also implement the Command interface) handled differently from built-in commands? (depends on T-17 plugin system analysis)</li><li><strong>OQ-2</strong>: The <code>insights.ts</code> command (3200 lines) seems like a candidate for decomposition into smaller modules — is this intentional or technical debt?</li></ul><h2 id="complexity-assessment" tabindex="-1">Complexity Assessment <a class="header-anchor" href="#complexity-assessment" aria-label="Permalink to &quot;Complexity Assessment&quot;">​</a></h2><ul><li><strong>LOW</strong></li><li>The command-handler pattern is structurally simple: a discriminated union type + lazy-loading convention + single-function handlers. Complexity arises only in individual handler implementations (e.g., <code>insights.ts</code>), not in the pattern itself.</li></ul>',61)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
